// Editorial quality overlay for IELTS category 2 / App IDs 48–216.
// The workbook order and grouping stay untouched.  These profiles replace
// mnemonic filler with four useful anchors: Chinese sound, reliable origin
// (kept on the base entry), an English sound/familiar-word bridge, and an
// exact semantic landing that also serves as the core image.

const E = (appId, soundHookZh, englishHookZh, imageLensZh) => [
  appId,
  { soundHookZh, englishHookZh, imageLensZh },
];

const entryProfiles = [
  E(48, "中文谐音：diversity 可记成‘地方色彩’——同一座城里装着不同口音、食物和生活方式；谐音只负责叫醒‘多样共存’。", "英文近音／熟词桥：先抓 diverse（多种不同的），再用 -ity 把形容词变成‘多样这种状态’。", "同一个生态圆环里同时长着不同物种：diversity 不是单纯数量多，而是一个整体内部在类型、身份或特征上存在差异；通常作不可数名词。"),
  E(49, "中文谐音：variety 像‘花儿挨地’——花圃里各种花挨在一起；若只指一种玫瑰，它又是一个具体品种。", "英文近音／熟词桥：various 是‘各种各样的’，vary 是‘发生变化’，variety 把这些不同种类收进一个名词。", "货架一边摆出 a wide variety of products，另一边只标 a new variety of wheat：variety 既可表示多种选择的范围，也可表示一个具体品种。"),
  E(50, "中文谐音：detect 像‘底下探’——探测器往表面底下扫，终于发现肉眼不明显的信号。", "英文近音／熟词桥：detector 是探测器；detect 是 detector 成功完成的动作，重点在‘已经发现存在’。", "雷达屏幕从空白到亮起微弱光点：detect 表示成功察觉隐藏、微弱或不明显的事物，常接 signal、disease、change；它不是仍在寻找的过程。"),
  E(51, "中文谐音：seek 像‘细看’——一边细看地图一边寻找答案，但还没有保证找到。", "英文近音／熟词桥：seek—sought—sought 要整组记；seek advice / seek to do 都带主动追求目标的方向。", "人物朝远处目标持续伸手：seek 强调正式、有目的地寻找、争取或力图实现，并不保证成功；找到结果应落到 find 或 detect。"),
  E(52, "中文谐音：isolate 像‘一锁累它’——把目标单独锁进透明盒，切断与其余部分的连接。", "英文近音／熟词桥：island 是视觉桥：被 isolate 的对象像被移到孤岛；这是熟词画面，不是现代硬拆词根。", "网络中一枚节点被剪断连线并放入单独容器：isolate 强调从群体、混合物或传播链中分离，既可隔离病人，也可分离变量或物质。"),
  E(53, "中文谐音：inaccessible 可记成‘硬塞也进不去’——门太高、权限锁死，怎样都无法进入或获得。", "英文近音／熟词桥：access 是进入或使用的权限；in- 关闭 access，-ible 表示‘能够被……’，合起来就是无法接近。", "一扇没有楼梯且刷卡失效的门挡住地点、资料和人：inaccessible 表示物理上到不了、信息拿不到或人难以接近，不等于只是 temporarily closed。"),
  E(54, "中文谐音：avoid 像‘我绕的’——前方有坑，我提前绕开，不让接触或坏结果发生。", "英文近音／熟词桥：avoidable 是‘可避免的’；avoid doing 是主动绕开行为，不能说 avoid to do。", "行人在障碍发生前改变路线：avoid 强调预先不接触、不做或防止落入某结果，后接名词或 -ing；已经身陷危险再脱身更像 escape。"),
  E(55, "中文谐音：escape 像‘一丝缝’——被困后从门的一丝缝里逃出去。", "英文近音／熟词桥：键盘 Esc 让程序退出当前状态；escape 也强调从控制、危险或限制中成功脱离。", "危险已经围住人物，他从尚未封死的出口冲出：escape 关注‘从既成困境中脱身’，可作动词或名词；avoid 则往往在进入困境前绕开。"),
  E(56, "中文谐音：evitable 像‘一避它吧’——既然能避开，就不是 inevitable；但现代输出通常直接用 avoidable。", "英文近音／熟词桥：把 inevitable 的否定前缀 in- 拿掉可认出 evitable；构词对称不等于使用频率对称。", "巨石上的 in- 被移走，露出可绕行的小路：evitable 的确表示‘可避免’，却很少见；阅读要能认，写作优先选择自然高频的 avoidable。"),
  E(57, "中文谐音：budget 像‘把钱掰着’——有限的钱被掰成住房、教育和交通几份。", "英文近音／熟词桥：budget 与 budgetary 同族；on a tight budget 把‘钱有限’的使用限制一起记住。", "一个带刻度的钱袋把收入预先分到各项支出格：budget 既是一定时期的收支计划，也可作动词表示按预算安排；它不是资金本身的 fund。"),
  E(58, "中文谐音：fund 像‘分的’——公共资金从蓄水池分流到研究、医疗和学校项目。", "英文近音／熟词桥：funding 是得到或提供的资金；fund 作动词时直接表示为项目提供钱。", "资金池通过管道向具体项目输送现金：fund 可指一笔为特定目的准备的资金，也可表示资助；budget 是怎样规划钱，fund 是实际可用或拨出的钱。"),
  E(59, "中文谐音：financial 像‘钱发哪儿’——所有关于钱从哪来、发到哪去的事项都属于财务。", "英文近音／熟词桥：finance 是财务活动或资金；financial 是形容词标签，常见 financial support / crisis / institution。", "现金流、债务和投资文件统一盖上 FINANCIAL 印章：financial 只说明与资金管理有关，不能单独充当 budget 或 fund 那样的具体名词。"),
  E(60, "中文谐音：adapt to 像‘挨到它就变’——环境一变化，生物和计划便调整自己以适应它。", "英文近音／熟词桥：adaptation 是适应性改变；牢记 adapt A for B 与 adapt to B 的方向不同。", "变色龙随新环境改变颜色：adapt to 表示主体为新条件而调整；adapt a book for children 则是把对象改编给某用途，不能把两种结构混在一起。"),
  E(61, "中文谐音：alternative 像‘另投一条路’——主路不合适，就转投另一条可选路线。", "英文近音／熟词桥：alternate 有‘轮流’义，alternative 是可替代选项；alternatively 常在写作中引出另一方案。", "岔路牌给出真实可选的第二条路：alternative 作名词是替代方案，作形容词是可供替代的；an alternative to 后接被替换对象，不说 alternative of。"),
  E(62, "中文谐音：substitute 像‘速补位’——原成员离场，替补立刻站到同一位置完成任务。", "英文近音／熟词桥：体育里的 substitution 是换人；substitute A for B 表示用 A 替代 B，方向必须看 for。", "舞台空位由替补演员接管：substitute 强调一个对象实际取代另一个并承担其功能；alternative 只是可选方案，未必已经换上。"),
  E(63, "中文谐音：compensate 像‘空缺补上’——损失造成的缺口由金钱、时间或优势补平。", "英文近音／熟词桥：compensation 是补偿；compensate for a weakness 与 compensate somebody for loss 要分清受偿者和原因。", "天平一端放着损失，另一端不断补入钱或优势直到恢复平衡：compensate 既可赔偿某人，也可抵消不利影响，重点是补回失去的价值。"),
  E(64, "中文谐音：make up 像‘没空就补’——墙上缺一块，马上做一块补丁把缺口补齐。", "英文近音／熟词桥：make up 有‘组成、编造、和好、弥补’多义；在本组要锁定 make up for 的补偿结构。", "缺口被补丁填平：make up for 表示弥补损失、缺点或错过的机会；单独 make up 还可能指组成或编造，阅读时必须看 for 和宾语。"),
  E(65, "中文谐音：offset 像‘哦，反设’——把一个反向因素设上去，正好抵消原来的成本或排放。", "英文近音／熟词桥：offset 在图表和排版中是偏移量；在因果里则用反向效应抵消另一效应。", "天平上的收益向反方向压住成本：offset 强调两个量或影响相互抵消，常接 cost、emissions、disadvantage；compensate 更常突出补偿者或受偿者。"),
  E(66, "中文谐音：component 像‘各块碰拢’——零件逐块碰拢，才组成完整机器。", "英文近音／熟词桥：compose 是组成，component 是被组成进去的可辨认部件；component of 是高频结构。", "机器拆开后每个功能零件都贴上标签：component 是整体中可辨认、发挥特定作用的构成部分；proportion 则问某部分占整体多少。"),
  E(67, "中文谐音：proportion 像‘铺一 portion’——整张饼中铺开的那一份，就是它所占比例。", "英文近音／熟词桥：portion 是一份，proportion 把‘这一份相对整体有多大’数字化。", "饼图的一块扇区与整圆同时标出：proportion 表示部分相对于整体的比例，常用 proportion of；它不是物理部件本身的 component。"),
  E(68, "中文谐音：military 像‘密令特厉’——军队按严厉密令调动人员、基地和装备。", "英文近音／熟词桥：military 统摄 army、weapons、bases 和 strategy；它是军事体系的形容词或军方集合名词。", "军人、基地、训练和战略被同一军徽圈住：military 表示与武装力量或战争有关，范围大于单件 weapon，也不等于只指陆军的 army。"),
  E(69, "中文谐音：criteria 像‘可列条呀’——评审前把判断标准一条条列出来。", "英文近音／熟词桥：criterion 是单数，criteria 是复数；像 phenomenon / phenomena 一样成对背。", "评审表上并列三条门槛，每条是 a criterion，合在一起才是 criteria：不要把复数 criteria 当单数写 a criteria，也别与一般标准 standard 混掉数。"),
  E(70, "中文谐音：standard 像‘站得住’——对象必须达到标尺线，质量才站得住。", "英文近音／熟词桥：standardized test 用统一尺度测所有人；meet a standard 表示达到要求。", "统一标尺放在多个对象旁边比较：standard 可指质量水平、规范或衡量尺度；criterion 是作决定时的一条具体判断条件，criteria 才是多条。"),
  E(71, "中文谐音：curriculum 像‘课里全’——一整个学习阶段要教的目标、内容与课程全装在路线图里。", "英文近音／熟词桥：extracurricular 是课外的；去掉 extra-，curricular / curriculum 就回到正式课程体系。", "从入学到毕业的课程地图连接学科、目标和顺序：curriculum 是整体教育方案；syllabus 通常只说明一门课每周教什么、怎样评分。"),
  E(72, "中文谐音：syllabus 像‘细列吧’——把一门课的主题、作业和评分细细列出来。", "英文近音／熟词桥：把 syllabus 当 course outline 熟词桥；它与 syllable 只是形近，不能当作同根。", "一门课程的文件按周列出阅读、作业和考核：syllabus 范围小于 curriculum，通常属于单门课；复数 syllabuses 或 syllabi 都可见。"),
  E(73, "中文谐音：feasible 像‘费事不？’——先过技术、时间和成本三关，确认这事做得成。", "英文近音／熟词桥：feasibility study 就是可行性研究；feasible 回答 can it be done，而非 is it ideal。", "方案穿过资源、时间和技术闸门后获准执行：feasible 强调实际能做成；realistic 强调符合现实，viable 还要求能够持续生存或成功。"),
  E(74, "中文谐音：realistic 像‘real 实的’——目标必须落到真实数据和资源上，不能漂在空中。", "英文近音／熟词桥：reality 是现实；realistic 把计划送去接受现实条件检验。", "云端目标被拉回地面并贴上真实成本与能力：realistic 表示符合现实、不过分理想化；它不保证技术上 feasible，也不保证长期 viable。"),
  E(75, "中文谐音：viable 像‘活呀不？’——方案不仅能启动，还要有心跳、能活下去。", "英文近音／熟词桥：vital 围绕生命，viable 也保留‘能活、能持续’的核心；常见 viable option / business。", "项目通过闸门后仍有稳定心跳：viable 强调能够长期运行、发展或盈利；feasible 只确认可以实施，不自动确认可持续。"),
  E(76, "中文谐音：constrain 像‘捆得紧’——绳索把预算、选择和行动范围捆窄。", "英文近音／熟词桥：constraint 是限制条件；constrain 是把这种限制施加到对象上的动作。", "系统向外扩张时被绳圈勒住：constrain 强调压缩选择、资源或发展空间，常见 be constrained by；stop 是完全停止，control 只是管理或掌控。"),
  E(77, "中文谐音：deficiency 像‘低于需’——实际量低于身体或系统所需的最低线。", "英文近音／熟词桥：deficient in 表缺乏，deficiency 是这种不足；与 deficit 都有低于需求的缺口感。", "营养刻度没有达到最低需求线：deficiency 强调某种必需物质、能力或制度要素不足，可造成问题；defect 更像一个具体瑕疵，shortage 偏供应量不够。"),
  E(78, "中文谐音：defect 像‘这地方裂’——质检员在产品上圈出一个明确裂点。", "英文近音／熟词桥：defective product 是有缺陷的产品；defect 作名词指具体问题，作动词另有叛逃义且重音不同。", "完整零件上只有一处裂纹被红圈标出：defect 通常是结构、设计或产品中的具体缺陷；deficiency 则更常是一种不足状态或缺少必需成分。"),
  E(79, "中文谐音：supplement 像‘速补满’——主体已有，再加一块材料把不足补满。", "英文近音／熟词桥：supplementary materials 是主教材之外的补充材料；supplement 不是完全替换主体。", "主模块旁装上一个附加模块：supplement 表示在已有基础上增加内容以完善或补足，常用 supplement A with B；provision 更强调预先提供或保障。"),
  E(80, "中文谐音：provision 像‘提前铺置’——看见未来需求，先把物资和条款铺置好。", "英文近音／熟词桥：provide 是提供，provision 是提供的安排、物资或合同条款；make provision for 是固定结构。", "计划者在需求出现前备好食物、资金和法律条款：provision 强调预先供应或安排，也可指合同条款；supplement 是在现有主体上追加补充。"),
  E(81, "中文谐音：distinguish 像‘盯细处’——盯住细节，终于把两个相似对象区分开。", "英文近音／熟词桥：distinct 是明显不同的；distinguish 是识别这种差异，常用 distinguish A from B。", "放大镜照出两片相似叶子的不同纹理：distinguish 强调看出或说明差别，也可表示使人显著；separate 只把对象分开，不一定理解差异。"),
  E(82, "中文谐音：differentiate 像‘difference 得出来’——用特征把相似对象分成不同类别。", "英文近音／熟词桥：different / difference 是熟词；differentiate 是执行区分，differentiation 还用于细胞分化和产品差异化。", "相似对象经过标记后形成不同类别：differentiate 既可辨别差异，也可使产品或细胞变得不同；distinguish 更常强调识别已经存在的区别。"),
  E(83, "中文谐音：analyze 像‘按来拆’——把复杂整体按部件拆开，再检查各部分关系。", "英文近音／熟词桥：analysis 是分析过程或结果，analyze 是动作；英式拼写名词仍是 analysis。", "复杂机器被拆成部件并沿连线追踪原因：analyze 是系统分解并解释关系；examine 可只是仔细检查，diagnose 则要识别具体问题或疾病。"),
  E(84, "中文谐音：diagnose 像‘点个病因’——把症状连成模式，最后点出问题名称。", "英文近音／熟词桥：diagnosis 是诊断结论，diagnose 是得出结论的动作；不要写成 diagnose of。", "零散症状被连成一个带名称的问题标签：diagnose 强调通过证据查明疾病或故障，常用 diagnose A as/with B；analyze 不一定给最终诊断。"),
  E(85, "中文谐音：emphasize 像‘俺放大’——把一句话加粗放大，让听者知道它尤其重要。", "英文近音／熟词桥：emphasis 是重点，emphasize 是把重点突出；直接接 importance / need，不要误加 on。", "普通文字中只有关键句被加粗并打上聚光灯：emphasize 表示明确突出重要性；focus on 说明关注对象，stress 可通过重音或反复强调。"),
  E(86, "中文谐音：focus on 像‘放镜头 on’——镜头对准一个对象，其余背景全部虚化。", "英文近音／熟词桥：camera focus 让主体清晰；focus attention/resources on 把注意力或资源集中到目标。", "相机只让一个目标清晰：focus on 强调把注意、研究或资源指向某对象，后接名词或 -ing；它不必声称该对象比其他内容更重要。"),
  E(87, "中文谐音：stress 像‘使它重’——给音节和观点都加上重量，于是它被特别听见。", "英文近音／熟词桥：word stress 是重音，mental stress 是压力；动词 stress 把观点‘读重’就是强调。", "同一只手给音节加重音、给句子加粗：stress 作动词可强调要点，语气常较强；作名词还表示压力，必须由搭配判断。"),
  E(88, "中文谐音：enormous 像‘一挪没门’——东西大到挡满门口，根本挪不动。", "英文近音／熟词桥：把 normal size 当基准，enormous 远超正常尺度；这是熟词桥，不把拼写硬拆成现代词根。", "普通刻度尺完全装不下对象：enormous 表示尺寸、数量或程度极大，强度高于 large；massive 常保留成块、厚重或规模庞大的感觉。"),
  E(89, "中文谐音：massive 像‘满是物’——厚重物体成块堆满整个空间。", "英文近音／熟词桥：mass 是质量或一大团；massive 保留大块、沉重和大规模的触感。", "一整块巨石压满画面：massive 常形容体量厚重、规模巨大或影响强烈；enormous 只强调非常大，large 则是最宽泛的普通大。"),
  E(90, "中文谐音：imitate 像‘一模一态’——动作、语调和姿态都照着样子模仿。", "英文近音／熟词桥：imitation 是仿制或模仿；imitate 强调根据已有样本复现，不等于创造原创版本。", "学习者像镜子一样复现老师的动作：imitate 可模仿行为、声音或风格，通常保留模仿者身份；mimic 往往复制得更细、更像。"),
  E(91, "中文谐音：mimic 像‘密密刻’——连对方的小动作和语调都密密复制下来。", "英文近音／熟词桥：mime 是无声表演，mimic 也围绕精确模仿；mimicry 是生物拟态。", "高精度复印机连语调、表情和节奏一起复制：mimic 比 imitate 更突出逼真细节，有时带嘲弄；在生物学中还可指拟态。"),
  E(92, "中文谐音：impair 像‘硬掰’——把完整功能硬掰出裂缝，仍能运作却明显变差。", "英文近音／熟词桥：impaired vision / hearing 是受损视力或听力；impairment 是功能损害。", "透明镜片出现裂纹但没有完全碎掉：impair 强调损害能力、判断或功能，使之下降；prevent 是阻止发生，damage 范围更宽。"),
  E(93, "中文谐音：diminish 像‘低迷呢’——音量和影响逐渐变低迷、变小。", "英文近音／熟词桥：dim 是变暗的熟词桥；diminish 像把亮度、数量或重要性一点点调低。", "音量旋钮缓慢向左转：diminish 可及物也可不及物，表示数量、强度或重要性逐渐减少；impair 更强调功能受损。"),
  E(94, "中文谐音：hinder 像‘横着挡’——路上横着障碍，车还能走但被拖慢。", "英文近音／熟词桥：hind 表后面；hinder 像把进程拖在后面，常接 progress / development。", "赛道上连续出现减速带：hinder 使行动更困难或更慢，但不一定完全阻止；prevent 则把结果挡在发生之前。"),
  E(95, "中文谐音：impede 像‘硬皮堵’——管道被一层硬皮堵住，流动明显受阻。", "英文近音／熟词桥：ped- 可联想到 foot，impede 像绊住脚步；这与其拉丁语‘束缚脚’历史图像一致。", "管道和道路都被障碍卡住：impede 较正式，强调阻碍移动、流动或进展，通常仍非完全阻断；hinder 适用范围更日常。"),
  E(96, "中文谐音：prevent 像‘提前拦’——事件还没到，门就先关上把它拦住。", "英文近音／熟词桥：pre- 是之前，prevent A from doing B 是在 B 发生前阻止 A。", "结果正要进门时被彻底挡在外面：prevent 强调使某事不发生，固定结构 prevent somebody/something from doing；不要省掉关键方向。"),
  E(97, "中文谐音：deter 像‘胆儿退’——高额罚款一亮，人的胆儿退了，主动放弃行动。", "英文近音／熟词桥：deterrent 是威慑物；deter A from B 强调通过恐惧成本劝退。", "警告牌没有锁门，却让来者自己掉头：deter 通过威胁、惩罚或困难降低行动意愿；prevent 则无论意愿如何都阻止结果。"),
  E(98, "中文谐音：obstacle 像‘挡车壳’——一个巨大车壳横在赛道中央，必须绕过。", "英文近音／熟词桥：obstacle course 是障碍赛；它是造成阻碍的具体名词，不是阻碍动作。", "赛道中央竖起实体或抽象墙：obstacle 指妨碍进展的事物或条件；hinder / impede 是动词，不能因中文都含‘阻碍’就混用词性。"),
  E(99, "中文谐音：legitimate 像‘立个准章’——主张经过规则与理由审查后盖上正当章。", "英文近音／熟词桥：legitimacy 是合法性或正当性；legitimate 不只问 law，也问理由是否可接受。", "一项权利依次通过法律门和合理性门：legitimate 可表示合法、正当或真实可信；legal 只确认符合现行法律，范围更窄。"),
  E(100, "中文谐音：legal 像‘立规了’——法律已经立下规则，符合它的才 legal。", "英文近音／熟词桥：legislation 是立法，legality 是合法性；legal 始终把判断锚定在法律制度。", "法典对行为亮绿灯：legal 表示法律允许或与法律有关，不自动表示道德正当、合情合理；后者常需 legitimate。"),
  E(101, "中文谐音：limitation 像‘里面有天花板’——能力走到里面的上限就无法再高。", "英文近音／熟词桥：limit 是边界，limitation 是边界本身或由它造成的缺点。", "研究方法头顶压着低天花板：limitation 常指能力、方法或条件的内在上限，也可指研究局限；restriction 更常是外部规则施加的限制。"),
  E(102, "中文谐音：restriction 像‘绳子收紧’——规则把行动范围用绳索收窄。", "英文近音／熟词桥：restrict 是限制动作，restriction 是具体规则或限制条件；常见 impose/lift restrictions。", "入口处规则牌与绳栏共同缩小可行动空间：restriction 多是外部制度或规定；limitation 还可表示事物自身能力有限。"),
  E(103, "中文谐音：convention 像‘众人开会定’——大家反复这样做，最后约定成默认规则。", "英文近音／熟词桥：conventional 是传统常规的；convention 还可指大型会议，需靠搭配区分。", "一群人把长期重复的做法写成默认规则：convention 可指社会习俗、艺术手法或大会；它不是普通 method，而是群体认可的惯例。"),
  E(104, "中文谐音：demanding 像‘得满顶’——任务把时间、技能和耐力要求都推到顶。", "英文近音／熟词桥：demand 是要求，demanding 描述需要大量努力或对人要求很高。", "任务山不断升高，完成者必须投入全部能力：demanding 表示费力、要求高，不等于 troublesome 的麻烦惹事；人也可 demanding，表示苛求。"),
  E(105, "中文谐音：determine 像‘定它明’——把模糊问题查明后定下来，也可直接决定结果。", "英文近音／熟词桥：determination 既是确定也可表示决心；determine whether / determine the cause 是高频学术结构。", "仪器先圈定唯一数值，决策者再锁定方案：determine 可‘查明’事实，也可‘决定’结果；decide 主要落在作出选择。"),
  E(106, "中文谐音：accelerate 像‘按下车来得快’——一踩加速器，速度或进程立刻提高。", "英文近音／熟词桥：accelerator 是油门或加速器；acceleration 是速度增加。", "时间轴被装上油门，事件间隔不断缩短：accelerate 可及物或不及物，表示加快速度、增长或变化；speed up 更口语。"),
  E(107, "中文谐音：ancient 像‘俺见久远’——眼前遗迹来自极其久远的时代。", "英文近音／熟词桥：ancient history / civilization 把词固定在历史久远；old 只说明年纪大。", "沙土覆盖数千年的城墙重新露出：ancient 通常指远古或历史早期的人、文明和遗迹；aged 多形容年老或陈年的对象。"),
  E(108, "中文谐音：beneficial 像‘benefit 效’——产生 benefit 的措施就是 beneficial。", "英文近音／熟词桥：benefit 是益处，beneficial to/for 表示对对象有好处；词尾 -cial 不改变语义核心。", "政策启动后健康、成本和环境指标变绿：beneficial 强调带来实际好处，常接 to；helpful 偏帮助完成任务，wholesome 常指有益身心。"),
  E(109, "中文谐音：wholesome 像‘whole 身’——完整健康的食物让 whole body 都受益。", "英文近音／熟词桥：whole 是完整，wholesome 指促进身体、心理或道德健康。", "一碗天然食物给身体和情绪同时充电：wholesome 常形容食物、活动或环境健康有益；beneficial 范围更广，可用于政策和技术效果。"),
  E(110, "中文谐音：chronic 像‘长日闹’——问题长时间反复闹，从不彻底消失。", "英文近音／熟词桥：chronology 与时间有关；chronic 也把重点放在长期持续或反复。", "同一个疼痛闹钟多年反复响：chronic 常指长期疾病或长期社会问题，通常带负面；lasting 只说明持续时间长，感情色彩更中性。"),
  E(111, "中文谐音：conscious 像‘看清时’——神志清醒时能看清信息并有意识选择。", "英文近音／熟词桥：consciousness 是意识状态；be conscious of 还可表示清楚意识到。", "大脑灯亮着并主动按下选择按钮：conscious 可指清醒、有意识的或意识到的；aware 主要表示知道某事实，不负责‘有知觉’状态。"),
  E(112, "中文谐音：aware 像‘啊，我 aware’——雷达一亮，你马上知道目标存在。", "英文近音／熟词桥：awareness 是认知或意识；be aware of / be aware that 是固定结构。", "雷达屏幕出现目标，观察者已知道它存在：aware 强调知情或察觉，通常作表语；conscious 还可指清醒和刻意的行为。"),
  E(113, "中文谐音：minimize 像‘迷你化’——把损失、风险或数量压到尽可能小。", "英文近音／熟词桥：minimum 是最小值；minimize 是朝最低可行水平压缩，不一定归零。", "控制旋钮被转到最低安全刻度：minimize 强调减少到最低程度，也可指淡化重要性；reduce 只表示减少，未必追求最小。"),
  E(114, "中文谐音：immunity 像‘一面免疫盾’——盾牌让身体免受病原，也让法律对象免于追责。", "英文近音／熟词桥：immune to 是免疫或不受影响，immunity 是这种保护状态。", "身体盾牌识别病原，法律盾牌挡住处罚：immunity 可指生物免疫力或法律豁免；resistance 只是抵抗能力，未必达到免受影响。"),
  E(115, "中文谐音：resistance 像‘力在相反处’——外来推力一来，墙从相反方向顶住。", "英文近音／熟词桥：resist 是抵抗，resistance 是抵抗力、阻力或反对；还可指电阻。", "一道墙顶住压力却未完全隔绝：resistance 强调对疾病、变化或力量的抵抗程度；immunity 更强，常表示不受特定病原影响。"),
  E(116, "中文谐音：imperative 像‘一命令，必执行’——红色命令灯亮起，行动不可拖延。", "英文近音／熟词桥：imperative mood 是祈使语气；an imperative 把‘必须做’名词化。", "红色警报把建议升级成必须：imperative 表示极其必要、紧迫，也可指命令或祈使语气；necessary 只说明不可缺少，未必有紧迫命令感。"),
  E(117, "中文谐音：necessary 像‘那是必须的’——缺少关键齿轮，机器就无法完成任务。", "英文近音／熟词桥：necessity 是必要性，necessarily 是必然地；拼写用 one collar, two sleeves 记 c/s 数量。", "机器少一个齿轮便不能运转：necessary 表示达成结果不可缺少；imperative 在必要之外更常带强烈紧迫或命令意味。"),
  E(118, "中文谐音：secrete 像‘细胞里释出’——腺体制造物质后从细胞里释放。", "英文近音／熟词桥：secretion 是分泌物或分泌过程；secrete 作‘分泌’读 /sɪˈkriːt/。", "腺体工厂制造并释放激素：secrete 专指细胞或腺体产生并释放物质；不要与 secret 的‘秘密’混淆，也不等于普通 discharge。"),
  E(119, "中文谐音：discharge 像‘底下闸开’——闸门打开，液体、电荷或病人被放出。", "英文近音／熟词桥：charge 是装载或电荷，dis- 表离开；discharge 把内容从系统释放出去。", "容器阀门打开，水、电荷和责任向外离开：discharge 强调排出、释放或准许离院；secrete 还包含生物体先制造该物质。"),
  E(120, "中文谐音：exude 像‘液体徐徐出’——树脂从表面小孔慢慢渗出。", "英文近音／熟词桥：exudate 是渗出物；exude confidence 把物理渗出扩展为自然散发气质。", "树皮缓慢冒出树脂，人物周围同时散发自信光环：exude 强调从表面渗出液体或自然流露品质；discharge 往往更直接、量更集中。"),
  E(121, "中文谐音：exaggerate 像‘一讲就加大’——小鱼经故事气泵一吹，变成巨鲸。", "英文近音／熟词桥：exaggeration 是夸张；overstate 是把程度说过头，语义相近但更正式直接。", "普通事实被气泵放大到超过真实比例：exaggerate 可夸大数量、困难或重要性，也可夸张动作；不是简单 emphasize 重点。"),
  E(122, "中文谐音：transmit 像‘穿过去递’——信息穿过通道，从发送端递到接收端。", "英文近音／熟词桥：trans- 是跨越，transmission 是传输或传播；发音桥直接抓 send across。", "信号、疾病或知识从一端跨到另一端：transmit 强调经媒介传送或传播，常见 transmit data/disease；transfer 更突出所有权或位置转移。"),
  E(123, "中文谐音：extinct 像‘熄停了’——物种生命树上的最后一盏灯彻底熄灭。", "英文近音／熟词桥：extinction 是灭绝，extinguish 是熄灭；两词共同帮助记‘火种不再延续’。", "生命树上某物种的最后一盏灯熄灭：extinct 是形容词，表示该物种已无活体成员；die out 是灭绝过程，不能把 extinct 当动词。"),
  E(124, "中文谐音：exclusive 像‘一圈只收这些’——VIP 圈只接纳特定成员，其他人被排除。", "英文近音／熟词桥：exclude 是排除，exclusive 把‘排他’变成性质；exclusive interview 还可表示独家。", "VIP 门只允许一组人进入：exclusive 可表示独有、排他的或高档专属的；only 只是限定数量或焦点，不自动带排斥和特权意味。"),
  E(125, "中文谐音：only 像‘only one’——聚光灯只照一个对象，其余全部暗下去。", "英文近音／熟词桥：only 的位置会改变焦点：only John / John only called / John called only Mary 含义不同。", "一束聚光灯随着 only 在句中的位置移动：only 只做数量或焦点限制；exclusive 描述对象本身具有独家、专属或排他性质。"),
  E(126, "中文谐音：guarantee 像‘盖个担保章’——承诺者盖章，并承担结果没实现的责任。", "英文近音／熟词桥：guaranteed result / money-back guarantee 把‘结果担保’与责任绑定。", "承诺在结果上盖章并附赔付责任：guarantee 强调确保结果或正式担保，可接名词或 that；assure 更常先让某个人放心。"),
  E(127, "中文谐音：assure 像‘啊，sure’——对担忧的人明确说：可以 sure，放心。", "英文近音／熟词桥：sure 是确定，assure somebody that... 是让某人确信；宾语通常是人。", "说话者把‘请放心’卡递给听者：assure 主要消除人的疑虑，常接 somebody；guarantee 更强调结果得到保证和承担责任。"),
  E(128, "中文谐音：inherit 像‘因上一代而得’——房产、基因甚至问题从上一代传到你手中。", "英文近音／熟词桥：inheritance 是遗产或遗传特征；inherited disease 把生物传递义固定下来。", "上一代把房产、特征和未解决问题装进传送箱：inherit 表示从前代、前任或既有系统接收，通常不是主动争取的 receive。"),
  E(129, "中文谐音：witness 像‘我亲眼见’——亲眼见到事件，才能成为目击者或作证。", "英文近音／熟词桥：eyewitness 是目击者；witness 既可作人，也可作动词‘见证’，还可指证据。", "一双眼睛把事件带进法庭和历史记录：witness 可指目击者、证据或亲历变化；view 只是观看，see 只是看见。"),
  E(130, "中文谐音：magnetic 像‘马上给你吸’——磁铁一靠近就把铁屑吸过来，人也可有吸引力。", "英文近音／熟词桥：magnet 是磁铁，magnetic 是有磁性的；magnetic personality 是比喻的强吸引力。", "磁场把铁屑和人群同时吸向中心：magnetic 首先指磁性，也可比喻极具吸引力；attractive 只说吸引人，不涉及磁学属性。"),
  E(131, "中文谐音：loss 像‘落失’——原来拥有的东西从账户里落出去，留下缺口。", "英文近音／熟词桥：lose 是动词，loss 是名词；weight loss / financial loss / loss of habitat 都围绕失去。", "数量、财产和关系从原有位置消失：loss 是失去后的缺口或损失结果；waste 是不当耗费，gone 是状态形容表达。"),
  E(132, "中文谐音：option 像‘任选项’——菜单上的每条路线都是一个可选项。", "英文近音／熟词桥：optional 是可选的，option 是可选择的具体方案；have no option but to 是固定结构。", "菜单同时列出几条可行路线：option 是可作选择的具体方案；choice 既可指选择行为，也可指选项，范围更宽。"),
  E(133, "中文谐音：prefer to 像‘偏放这头’——天平偏向更喜欢的一项。", "英文近音／熟词桥：preference 是偏好；prefer A to B 与 prefer to do rather than do 要分别记结构。", "两个行动放在天平两端，偏好的一端下沉：prefer to do 表示更愿做某事；比较对象用 prefer A to B，不用 than。"),
  E(134, "中文谐音：rather 像‘绕到另一边’——说话路线被 rather 修正到更准确或更偏好的方向。", "英文近音／熟词桥：would rather do A than do B 表偏好；or rather 表自我纠正，rather 还可表相当。", "句子箭头从原说法转向更合适说法：rather 功能多，既能构成偏好，也能修正或加强程度；不能把它单独等同 prefer to。"),
  E(135, "中文谐音：priority 像‘排第一题’——待办清单先把最重要的一题排到第一位。", "英文近音／熟词桥：prior 是在前的，priority 是被放在前面的事项或优先权；give priority to 是高频搭配。", "待办清单最上方一项被红框锁定：priority 表示必须先处理的重要事项或优先权；preference 只表示更喜欢，未必决定行动顺序。"),
  E(136, "中文谐音：preference 像‘偏爱放这份’——两项都可选，却更愿把手放在其中一份上。", "英文近音／熟词桥：prefer 是更喜欢，preference 是偏好本身；have a preference for 接偏好对象。", "两杯饮料都可用，一只手却偏向左杯：preference 表主观偏好；priority 是客观或决策上先处理的事项，两者可能并不一致。"),
  E(137, "中文谐音：primary 像‘排第一’——在作用、阶段或重要性上站到第一位。", "英文近音／熟词桥：prime 是首要，primary 也可指初级阶段；primary source 是第一手来源。", "领奖台第一名同时照亮‘主要’与‘最初阶段’标签：primary 可表示首要、主要或初级；main 更普通，principle 则是原理。"),
  E(138, "中文谐音：principle 像‘凭此立’——整套制度凭这条基本原则站立。", "英文近音／熟词桥：in principle 表原则上，principled 表有原则；牢记 principle 结尾 -ple，不是 principal。", "一条基本规则写在制度地基石上：principle 是指导行为、解释机制的原理或准则；primary 是形容词‘主要的’，两者不因原表拼写相近而同义。"),
  E(139, "中文谐音：main 像‘蛮重要’——所有支流都汇入最主要的河道。", "英文近音／熟词桥：main road / main reason / main point 都把对象置于中心；它是最通用的‘主要的’。", "一条最粗河流收拢全部支流：main 只标出最主要部分，语气宽泛；primary 更正式，也可表示第一阶段或第一手。"),
  E(140, "中文谐音：principle 像‘凭此立’——机器和制度都凭基本原理站得住。", "英文近音／熟词桥：principal 是校长或主要的，principle 是原则；把 -pal 想成 person，-ple 想成 rule。", "轴心规则驱动整台机器：principle 可指自然原理、道德原则或行动准则；rule 常是具体规定，范围和抽象程度较低。"),
  E(141, "中文谐音：potential 像‘破土前’——种子还没破土，内部已藏着未来大树的潜能。", "英文近音／熟词桥：potentially 是潜在地；potential for / potential to do 分别接名词和动作。", "种子内部映出尚未实现的大树：potential 作名词是可发展能力，作形容词是可能成为；possibility 只表示发生可能，不强调内在能力。"),
  E(142, "中文谐音：quantity 像‘看其量体’——用量杯或计数器看对象到底有多少。", "英文近音／熟词桥：quantitative 是定量的，quantify 是量化；quant- 词族始终围绕多少。", "量杯与计数器共同显示总量：quantity 可用于可数或不可数事物的量，强调数量维度；number 通常只与可数名词对应。"),
  E(143, "中文谐音：settle 像‘使它落’——争议落定，悬浮颗粒也落到杯底。", "英文近音／熟词桥：settlement 可指解决、定居点或结算；多个义项都带‘从不稳到安定’。", "争议双方握手，尘土同时沉底：settle 可解决争端、结清款项、定居或稳定下来；fix 偏修好，figure out 偏想明白。"),
  E(144, "中文谐音：sophisticate 像‘设备升级太复杂’——简单机器层层加装精密模块。", "英文近音／熟词桥：sophisticated 常表示复杂先进或世故；动词 sophisticate 较少见，表示使复杂或精致化。", "简单装置被加上多层传感器与控制系统：sophisticate 强调使之更复杂、精密或世故，现代更常见过去分词 sophisticated；不是所有 complicate 都带先进感。"),
  E(145, "中文谐音：complicate 像‘拐弯铺开’——直路突然长出许多交叉口，事情变难。", "英文近音／熟词桥：complication 是并发问题或复杂因素；complicated 强调难以理解或处理。", "清晰路线图突然长出十个交叉路口：complicate 是使问题更难、更复杂，通常带负面；sophisticate 还可能表示提升精密程度。"),
  E(146, "中文谐音：specific 像‘锁定细格’——聚光灯锁定一个明确类别、目标或细节。", "英文近音／熟词桥：specify 是明确说明，specification 是规格；be specific about 是高频结构。", "聚光灯只照编号 27 的目标：specific 强调明确限定而非泛泛，也可表示某个特定对象；detailed 强调细节丰富，particular 强调某一个。"),
  E(147, "中文谐音：detailed 像‘细节都列’——地图把每条小巷和门牌都列清。", "英文近音／熟词桥：detail 是细节，detailed 是含有大量具体细节；a detailed account 是高频搭配。", "放大镜下地图显出每条小巷：detailed 强调信息充分、细节多；specific 只需足够明确，未必篇幅很长或细节很多。"),
  E(148, "中文谐音：particular 像‘把它挑出来’——从一群相似对象中单独点出一个。", "英文近音／熟词桥：in particular 是尤其，be particular about 是挑剔；particular 始终带选择性聚焦。", "一排相同杯子中只有一个被手指点中：particular 表某个特定对象或特别讲究；specific 更强调说明准确、边界明确。"),
  E(149, "中文谐音：survive 像‘死里还在’——风暴过后仍活着、仍存在。", "英文近音／熟词桥：survival 是生存，survivor 是幸存者；survive 可直接接事故或某人。", "暴风后唯一一棵树仍站立并发芽：survive 强调经受危险、时间或淘汰后继续活着/存在；remain 只说明仍处于某状态。"),
  E(150, "中文谐音：swift 像‘嗖，飞特快’——动作像箭一样迅速又利落。", "英文近音／熟词桥：swift response / action 常见于正式语境；swiftly 是副词。", "闪电抢在计时器跳秒前完成动作：swift 强调快速、及时且动作顺畅；quick 最通用，rapid 常强调变化或连续过程速度快。"),
  E(151, "中文谐音：unexpectedly 像‘预期线外一拐’——真实结果突然跑出预测路线。", "英文近音／熟词桥：expected 前加 un- 再加 -ly：从‘预期的’变成‘出乎意料地’。", "预测曲线向上，真实数据却突然向下：unexpectedly 是副词，修饰发生方式；surprising 是形容词，描述事物让人惊讶。"),
  E(152, "中文谐音：surrounding 像‘四周都绕着’——中心物被山、水与街道环绕。", "英文近音／熟词桥：surround 是环绕，surroundings 常用复数表示周围环境；形容词 surrounding 修饰周边事物。", "中心小屋被一圈山水包住：surroundings 指某地点周围可见环境，通常复数；environment 更广，包含物理、社会和制度条件。"),
  E(153, "中文谐音：setting 像‘设定舞台’——同一事件放到不同舞台背景，意义也改变。", "英文近音／熟词桥：set 是放置或设定，setting 就是故事、研究或设备被放置的背景和配置。", "同一人物先后进入课堂、村庄和医院舞台：setting 强调事件发生的具体时间地点或背景；surroundings 偏周围景物，environment 范围更系统。"),
  E(154, "中文谐音：environment 像‘around 的大圈’——空气、水、制度与人群共同包围主体。", "英文近音／熟词桥：environmental issues 是环境问题；environment 不只自然，也可指工作或学习环境。", "空气、水、建筑和社会规则组成一个生态罩：environment 是影响生物或人的整体条件系统；setting 更具体，surroundings 更偏眼前周边。"),
  E(155, "中文谐音：attempt 像‘按台阶试攀’——向目标抓去一次，成功与否尚未确定。", "英文近音／熟词桥：attempt to do / make an attempt 是高频结构；attempt 本身不保证结果。", "攀登者第一次伸手抓向高台：attempt 是有意完成困难任务的一次尝试，可作名词或动词；test 更偏检验，try 更日常。"),
  E(156, "中文谐音：expertise 像‘expert 的本事’——专家知识与长期实践合成专业能力。", "英文近音／熟词桥：expert 是专家，expertise 是其专业知识与技能；通常不可数。", "知识书本与实践工具合成专家徽章：expertise 指某领域经过训练积累的专门能力；knowledge 可只是知道，skill 可是单项技巧。"),
  E(157, "中文谐音：faculty 像‘发出能力’——大脑发出能力按钮；大学里则是一整个院系或教员群体。", "英文近音／熟词桥：faculty of memory 是心智能力，Faculty of Science 是理学院；靠 of 后宾语判义。", "大脑能力按钮连接一座大学楼：faculty 可指天赋能力、大学院系或全体教员；ability 只覆盖能力义，不能替换组织义。"),
  E(158, "中文谐音：donate 像‘都拿去’——把钱、血或物品无偿拿给公益对象。", "英文近音／熟词桥：donation 是捐赠物，donor 是捐赠者；donate A to B 明确物与受赠方。", "双手把血袋与钱箱递给机构：donate 强调无偿正式捐赠具体东西；contribute 还可贡献时间、意见或作为原因促成结果。"),
  E(159, "中文谐音：contribute 像‘共同添一块’——每个人添一块拼图，项目才完成。", "英文近音／熟词桥：contribution 是贡献；contribute to 可表示贡献给，也可表示导致。", "多人各自把一块拼图放进共同成果：contribute 强调提供一部分或促成结果，范围比 donate 宽；捐钱可两者皆用，但语气侧重不同。"),
  E(160, "中文谐音：dynamics 像‘动力们在互动’——多股力量互推，系统走势不断变化。", "英文近音／熟词桥：dynamic 是动态的，dynamics 是力量互动及变化规律；形式常为复数但可作学科名。", "多枚齿轮彼此推动并改变系统方向：dynamics 指群体或系统内部力量关系及变化机制，不等于单一 energy、force 或 move。"),
  E(161, "中文谐音：incentive 像‘引着你行动’——目标前的奖励把人引向行动。", "英文近音／熟词桥：incentivize 是提供激励，incentive to do / for doing 都可见。", "奖金像胡萝卜挂在目标前：incentive 是外部奖励或条件，用来提高行动意愿；motive 是内部原因，stimulus 是触发反应的刺激。"),
  E(162, "中文谐音：motive 像‘move 的内力’——胸口隐藏齿轮推动人物行动。", "英文近音／熟词桥：motivation 是动机与动力，motive 尤常问某个行为背后的原因。", "人物胸口的齿轮把行为向前推：motive 是行动背后的内在原因，常用于调查犯罪；incentive 更常是外部诱因。"),
  E(163, "中文谐音：stimulus 像‘刺激一来立刻动’——一束光触发感应器响应。", "英文近音／熟词桥：stimulate 是刺激动作，stimulation 是过程；stimulus 是具体刺激，复数 stimuli。", "光束击中感应器并触发反应：stimulus 是引起生理、心理或经济反应的因素；incentive 特别针对有意行动与奖励。"),
  E(164, "中文谐音：mortality 像‘末日率’——统计一群生命在一定时期内死亡的比例。", "英文近音／熟词桥：mortal 是会死的，mortality 是死亡现象或死亡率；mortality rate 是标准搭配。", "人口表上的生命灯按时间熄灭并形成比率：mortality 常指群体死亡率或人终有一死的状态；death 可指单次死亡，不自动带统计含义。"),
  E(165, "中文谐音：peripheral 像‘边儿浮着’——小点浮在圆心之外的边缘。", "英文近音／熟词桥：periphery 是外围，peripheral 是位于外围或相对次要；peripheral vision 是周边视觉。", "圆心之外的小点在边缘闪烁：peripheral 可指空间外围，也可指议题中次要部分；minor 只说明较小或较次要，不含外围位置。"),
  E(166, "中文谐音：vicinity 像‘围起近地’——地图图钉周围画一圈附近区域。", "英文近音／熟词桥：in the vicinity of 是固定正式表达；vicinity 是区域名词，nearby 常作副词或形容词。", "地点图钉周围画出近距离半径：vicinity 指某地点附近区域，常用 in the vicinity；neighbourhood 还可指社区，nearby 词性不同。"),
  E(167, "中文谐音：threaten 像‘推着危险来’——乌云和警告逼近目标，可能造成伤害。", "英文近音／熟词桥：threat 是威胁，threaten to do 表扬言，threaten A with B 表用 B 威胁 A。", "危险乌云逼近村庄但后果尚未发生：threaten 可发出威胁或使对象面临风险；endanger 直接把对象置于危险中。"),
  E(168, "中文谐音：endanger 像‘引到 danger’——一只手把对象推入危险区。", "英文近音／熟词桥：danger 清楚藏在 endanger 中；endangered species 是濒危物种。", "对象越过红线进入危险区：endanger 表使人、物种或计划处于受伤害风险中；threaten 可只是预示危险或发出威胁。"),
  E(169, "中文谐音：jeopardize 像‘奖杯压在线上’——重要成果悬在线上，随时可能失去。", "英文近音／熟词桥：put in jeopardy 与 jeopardize 同义；常接 career、safety、negotiations。", "关键奖杯挂在断裂细绳上：jeopardize 强调使已有的重要事物面临丧失或失败；endanger 更常涉及安全、生命或生存。"),
  E(170, "中文谐音：risk 像‘冒险一试’——把筹码推向可能获利也可能损失的转盘。", "英文近音／熟词桥：at risk / risk doing / risk of 构成三条高频结构；risk 可名可动。", "人物把筹码推向不确定转盘：risk 是损失发生的可能性或主动承担这种可能；hazard 是具体危险源，threaten 是造成威胁的动作。"),
  E(171, "中文谐音：hazard 像‘害在这儿’——裸露电线就是摆在眼前的具体危险源。", "英文近音／熟词桥：hazardous 是危险的；health hazard / fire hazard 都指可识别的危险因素。", "地面裸线旁竖起警示牌：hazard 是可能造成伤害的具体因素或条件；risk 是伤害发生的概率与后果组合，也可作动词。"),
  E(172, "中文谐音：practice 像‘排着练’——同一动作排着反复做，最后成为惯常做法。", "英文近音／熟词桥：practise 是英式动词拼写，practice 是英式名词；美式通常都写 practice。", "动作被反复训练并沉淀成固定做法：practice 可指练习、惯例或实际实施；method 是方法，exercise 是具体练习项目。"),
  E(173, "中文谐音：bacteria 像‘把细菌列一排’——显微镜下多枚单细胞微生物排开。", "英文近音／熟词桥：bacterium 是单数，bacteria 是复数；bacterial 是形容词。", "显微镜下多枚单细胞小棒带着有益和有害标签：bacteria 是细菌复数，既可能致病也可能有益；virus 不是细胞，microbe 范围更广。"),
  E(174, "中文谐音：virus 像‘微入细胞’——微小颗粒进入细胞，借宿主机器复制。", "英文近音／熟词桥：viral 是病毒的或像病毒般传播的；virus 与 bacteria 生物类别不同。", "非细胞颗粒劫持宿主细胞复制机器：virus 必须依赖宿主复制；bacterium 是细胞生物，抗生素不能自动治疗病毒。"),
  E(175, "中文谐音：germ 像‘病菌总称’——日常把能致病的微小东西统装进 germ 袋。", "英文近音／熟词桥：germ 还可指萌芽或起源；germ theory 中则泛指致病微生物。", "卡通小怪物袋装进细菌、病毒等病原：germ 是日常非技术总称，范围取决语境；科学分类要选 bacteria、virus 或 microbe。"),
  E(176, "中文谐音：microbe 像‘微小生物’——显微镜伞下聚集多类微小生命。", "英文近音／熟词桥：micro- 是微小，microbiology 是微生物学；microbe 是广义微生物。", "显微镜下细菌、原生生物和微小真菌集合：microbe 是广义微生物，未必致病；germ 更常暗示病原，virus 是否算 microbe 依定义语境。"),
  E(177, "中文谐音：be subject to 像‘在规则伞下’——对象处在法律、审查或变化支配之下。", "英文近音／熟词桥：subject 有‘受制于’与‘主题’多义；be subject to 后接规则、变化或批准。", "方案站在法律、税收和变化三把伞下：be subject to 表受……约束、可能遭受或须经……，不是简单 face；语义由后接名词决定。"),
  E(178, "中文谐音：be liable to 像‘来不来？很可能’——警报提示某事容易发生，也可能负法律责任。", "英文近音／熟词桥：liability 是责任或负债；liable to do 表很可能，liable for 表负有责任。", "一只手拿法律账单，另一只手拿概率警报：be liable for 与 be liable to 结构不同；potential 只是潜在，不自动表示法律责任或较高倾向。"),
  E(179, "中文谐音：innate 像‘一生内带’——出生时程序已写在身体或头脑里。", "英文近音／熟词桥：native 与出生地相关，innate 也抓 nat- 的出生线索；inborn 是最直接熟词替换。", "能力像出生时预装的程序：innate 强调不是后天学习而来的天生特质或能力；built-in 还可指设备内置，inborn 主要用于生物或人格。"),
  E(180, "中文谐音：pattern 像‘排成图’——重复元素排成可识别的图样或规律。", "英文近音／熟词桥：pattern recognition 是模式识别；behaviour pattern / weather pattern 都强调反复结构。", "多个数据点连成重复而可辨的形状：pattern 可指视觉图案、行为方式或数据规律；formation 更强调形成过程或形成后的结构。"),
  E(181, "中文谐音：formation 像‘放成一形’——零散部分聚合后放成一个新结构。", "英文近音／熟词桥：form 是形态，formation 是形成过程或结果；formation of 接形成之物。", "云粒聚成云层，队员排成队形：formation 强调形成及形成后的结构；pattern 关注重复规律，不必说明怎样形成。"),
  E(182, "中文谐音：therapy 像‘他人陪你’——治疗师陪患者通过持续治疗恢复功能。", "英文近音／熟词桥：therapist 是治疗师，therapeutic 是有治疗作用的；therapy 常指一套持续干预。", "患者沿着连续疗程逐步恢复：therapy 常指心理、物理或药物治疗方案；treatment 范围更广，可是一次处理或总体治疗。"),
  E(183, "中文谐音：original 像‘origin 来的’——时间线起点和未经复制的新创意都从这里开始。", "英文近音／熟词桥：origin 是起源，original 可表示最初的、原件或原创的；靠名词搭配判义。", "一边是时间线起点，一边是无复制痕迹的作品：original 既可指最初版本，也可指新颖原创；initial 只强调开始阶段。"),
  E(184, "中文谐音：initial 像‘一开始那格’——项目时间线第一格被高亮。", "英文近音／熟词桥：initially 是起初，initial stage / response 都落在开始时；initial 还可指姓名首字母。", "时间轴第一格亮起而后续仍空白：initial 强调顺序上的最初阶段或第一反应；original 还可能表示原件与原创。"),
  E(185, "中文谐音：confidential 像‘封紧档案’——机密文件封紧，只给被信任者看。", "英文近音／熟词桥：confidence 是信任，confidential 信息正因为托付信任而受保护；confidentiality 是保密性。", "文件锁进授权保险柜：confidential 指仅限特定人员知悉的信息或关系；secret 更一般，undisclosed 只说明尚未公开。"),
  E(186, "中文谐音：cognitive 像‘靠脑认知的’——记忆、注意与推理都在大脑控制台运行。", "英文近音／熟词桥：cognition 是认知，cognitive 是形容词；cognitive ability / process 是学术高频。", "大脑控制台同时处理记忆、语言和推理：cognitive 专指获取、处理和使用知识的心理过程；mental 范围更广，还包括情绪与心理健康。"),
  E(187, "中文谐音：comply with 像‘全盘配合’——行动逐条对齐规则清单。", "英文近音／熟词桥：compliance 是合规，compliant 是顺从或合规的；comply 必须与 with 搭配。", "组织把每项操作对齐法规：comply with 强调遵守规则、要求或标准，语体正式；obey 更常直接接命令或权威。"),
  E(188, "中文谐音：obey 像‘哦，照办’——命令一来，行动者立即照办。", "英文近音／熟词桥：obedience 是服从，obedient 是听从的；obey 直接接 person/order/law，不加 with。", "权威发出命令，行动者按要求执行：obey 强调服从人或命令；comply with 更正式，常用于法规、标准和程序。"),
  E(189, "中文谐音：consult 像‘看手册再商量’——决策前既查资料，也向专家请教。", "英文近音／熟词桥：consultant 是顾问，consultation 是咨询；consult a doctor 不加 with，consult with 可表共同商议。", "一个人同时打开资料库并召集专家：consult 可查阅资料、请教专业人士或商议；ask for advice 只覆盖请教义。"),
  E(190, "中文谐音：superior 像‘上面一层’——比较阶梯上站得更高，也可能是职位上级。", "英文近音／熟词桥：super- 是在上，superior to 用 to 不用 than；superiority 是优越性。", "比较天平一端升高并连接上级办公室：superior 可指质量更好、级别更高或上级，固定比较结构 superior to；higher / upper 不覆盖全部评价义。"),
  E(191, "中文谐音：co-operation 像‘口令一致一起做’——多人按同一口令协作完成任务。", "英文近音／熟词桥：co- 是共同，operate 是运作；co-operation 就是共同运作，英式可写 cooperation。", "多人把不同齿轮接成一台机器：co-operation 强调各方共同努力；support 可是单向帮助，work together 是更口语的表达。"),
  E(192, "中文谐音：co-ordinate 像‘共同定节拍’——指挥者让不同部分按同一时间表配合。", "英文近音／熟词桥：coordinate 可作动词、名词或形容词；coordination 是协调过程。", "指挥棒让车辆、人员和时间表同步：co-ordinate 强调安排不同部分使其有效配合；organize 偏建立秩序，harmonize 偏消除冲突。"),
  E(193, "中文谐音：organize 像‘各归各盒’——杂乱卡片按类别进入文件盒。", "英文近音／熟词桥：organization 是组织或整理结果；organize information/events 都强调安排秩序。", "散乱资源被分类、排序并分配责任：organize 使事物结构清楚、可执行；co-ordinate 更强调多个已存在部分之间的同步。"),
  E(194, "中文谐音：harmonize 像‘和声一致’——冲突音符被调到相容和弦。", "英文近音／熟词桥：harmony 是和谐，harmonize 是使相互协调；harmonize A with B 是常见结构。", "不协调音符被调整后共同成和弦：harmonize 强调消除差异、使规则或颜色相容；co-ordinate 更偏安排时间与行动配合。"),
  E(195, "中文谐音：differ 像‘地方不同’——两个对象并排后显出性质差异。", "英文近音／熟词桥：different 是不同的，difference 是差异；differ from 与 differ in 分别引出对象和方面。", "两件样本在比较板上显出不同纹理：differ 陈述 A 与 B 不同，或意见不一致；vary 更常表示同一事物随条件变化或一组内部有差异。"),
  E(196, "中文谐音：vary 像‘歪来歪去’——同一旋钮随时间和条件不断改变刻度。", "英文近音／熟词桥：various 是各种的，variation 是变化；vary from A to B 表范围。", "同一数值曲线随条件上下移动：vary 可指随时间变化，也可指组内彼此不同；differ 通常直接比较两个对象或观点。"),
  E(197, "中文谐音：cue 像‘Q 灯一亮’——舞台提示灯亮，演员知道该行动。", "英文近音／熟词桥：take your cue from 是照提示行动；cue 可名可动，queue 则是排队。", "舞台灯给出触发行动的信号：cue 通常是约定的提示，促使反应、记忆或下一步；hint 轻微暗示，clue 帮助找答案。"),
  E(198, "中文谐音：hint 像‘很轻提示’——答案只从帘后露出一点轮廓。", "英文近音／熟词桥：drop a hint 是暗示，hint at 只轻轻指向而不明说。", "半透明帘子只露出答案一角：hint 是间接、轻微的提示或迹象；clue 往往是推理证据，cue 则触发预定行动。"),
  E(199, "中文谐音：clue 像‘线索串一路’——侦探把碎片一路串到答案。", "英文近音／熟词桥：clueless 是毫无线索，a clue to 接答案对象；clue 常与调查、谜题搭配。", "证据碎片被细线连接成结论：clue 是帮助发现答案或解释的线索；hint 可能由人有意暗示，cue 用来提示何时行动。"),
  E(200, "中文谐音：signal 像‘信息给了’——发送端亮灯，把信息给接收端。", "英文近音／熟词桥：signal strength / signal that... 分别是物理信号与表明；signal 可名可动。", "发送端发出可被识别的信息，接收端据此响应：signal 可以是约定信号或征兆；symbol 代表概念，但不一定传递行动信息。"),
  E(201, "中文谐音：symbol 像‘形标’——一个具体图形被当作抽象概念的标记。", "英文近音／熟词桥：symbolic 是象征性的，symbolize 是象征；词族都围绕代表意义。", "鸽子图形背后站着‘和平’概念：symbol 是代表另一事物或观念的符号；signal 重点在传递信息或提示反应。"),
  E(202, "中文谐音：abandon 像‘啊，搬走’——把责任和物品都搬开，从此不再照管。", "英文近音／熟词桥：a band on stage 演完 with abandon，又把乐器 abandoned；同一句串起放纵与抛弃。", "双手彻底松开计划、岗位或船只：abandon 强调彻底放弃并停止负责；with abandon 则是无拘束地行动，两个义项都来自‘松开控制’。"),
  E(203, "中文谐音：halt 像‘喊停’——紧急一喊，列车和进程立刻停止。", "英文近音／熟词桥：come to a halt 是停下来，bring A to a halt 是使 A 停止；halt 可名可动。", "紧急刹车让运行过程停止在原地：halt 强调暂时或突然停止，语体较正式；abandon 是彻底放弃，不只是暂停。"),
  E(204, "中文谐音：fragile 像‘非常易裂’——玻璃生态球轻轻一碰就碎。", "英文近音／熟词桥：fragment 是碎片的熟词桥；fragile 表容易破碎或受损。", "薄玻璃球承受很小冲击就裂开：fragile 强调物体、关系或生态系统本身容易破损；vulnerable 强调暴露于攻击或伤害。"),
  E(205, "中文谐音：vulnerable 像‘无铠能被伤’——没有盔甲，站在风险入口。", "英文近音／熟词桥：vulnerability 是脆弱性，vulnerable to 接具体威胁。", "没有防护的人暴露在风暴前：vulnerable 强调因缺乏保护而易受某种伤害；fragile 强调本身易碎，未必已有外部威胁。"),
  E(206, "中文谐音：retain 像‘仍在’——信息、员工和水经过变化后仍被留在系统里。", "英文近音／熟词桥：retention 是保留或记忆保持；retain information / staff / heat 都很高频。", "容器双手把原有内容留住：retain 表继续拥有、保持或记住，不是普通 maintain 的‘维持状态’，也不只限记忆。"),
  E(207, "中文谐音：vanish 像‘哇，没了’——烟雾一过，物体突然完全消失。", "英文近音／熟词桥：vanishing point 是消失点；vanish 是不及物动词，不能直接说 vanish something。", "物体从画面瞬间归零且不留痕迹：vanish 强调突然或完全消失；disappear 更通用，可不带神秘或彻底感。"),
  E(208, "中文谐音：delivery 像‘递那里’——包裹、服务或演讲被递到目标端。", "英文近音／熟词桥：deliver 是递送或发表，delivery 是过程、方式或分娩；靠宾语场景判义。", "包裹、讲话和医疗服务沿不同通道到达接收者：delivery 不仅是送货，也可指服务提供、演讲方式或分娩；send 只是发送动作。"),
  E(209, "中文谐音：erode 像‘日磨的’——海浪日复一日磨掉岩石和信任。", "英文近音／熟词桥：erosion 是侵蚀过程；erode confidence / soil 把物理磨损扩展到抽象削弱。", "海浪一层层带走岩石，信任墙也同步变薄：erode 强调长期渐进侵蚀；rust 只指锈蚀，damage 不说明渐进机制。"),
  E(210, "中文谐音：induce 像‘引得出’——外部因素引得反应、睡眠或变化发生。", "英文近音／熟词桥：induction 是诱导或归纳；induce A to do 与 induce a response 都常见。", "外部刺激按下按钮触发结果：induce 较正式，表示促使人行动或引起生理反应；cause 最宽，lead to 更突出因果链。"),
  E(211, "中文谐音：stable 像‘四腿稳’——桌子四脚牢固，曲线不大波动。", "英文近音／熟词桥：stability 是稳定性，stabilize 是使稳定；stable condition / price 都高频。", "四脚桌和数据曲线都保持平稳：stable 表不易改变、倒塌或波动；constant 更强调数值持续不变，unchanged 只陈述未变化。"),
  E(212, "中文谐音：integrate 像‘一体给它’——不同模块被接成一体并共同运转。", "英文近音／熟词桥：integer 是完整数的熟词桥，integration 是整合；integrate A into/with B 注意方向。", "不同模块卡入同一机器并互相协作：integrate 不只是 combine 放在一起，而是让部分进入统一系统、发挥共同功能。"),
  E(213, "中文谐音：equal 像‘一块儿平’——天平两端同高，数量、地位或能力相等。", "英文近音／熟词桥：equality 是平等，equally 是同等地；be equal to 还可表示胜任。", "天平两端完全平衡，参与者站在同一高度：equal 强调数量、价值或地位相同；fair 强调合理公正，even 可指均匀或平坦。"),
  E(214, "中文谐音：fair 像‘分得合理’——裁判按需要与规则合理分配，而非机械平均。", "英文近音／熟词桥：fairness 是公平，fair trial / fair share 落在公正；fair 还可表示天气晴朗。", "裁判依据一致规则作出合理决定：fair 关注程序与待遇是否公正，不要求每个人得到完全 equal 的数量。"),
  E(215, "中文谐音：even 像‘压一遍’——滚筒压一遍，表面平整、分布均匀。", "英文近音／熟词桥：evenly 是均匀地，even number 是偶数；多义需靠搭配分开。", "滚筒把表面压平并把资源铺匀：even 可表示平坦、均匀、相等或偶数；equal 更明确比较两者相同，fair 判断公正。"),
  E(216, "中文谐音：grant 像‘盖章给’——权威盖章后正式给出资金、许可或权利。", "英文近音／熟词桥：grant application 是拨款申请；grant permission / grant access 都带正式授权。", "权威把许可、权利或资金盖章交付：grant 强调有权者正式授予，也可表示勉强承认；offer 只是提出给予，未必已经批准。"),
];

